1	import { useEffect, useRef, useState } from 'react';
2	import type { RefObject, SyntheticEvent } from 'react';
3	import { defineMessages, useIntl } from 'react-intl';
4	import { useUiCopy } from 'app/hooks/useUiCopy';
5	import { useForm } from 'react-hook-form';
6	import type { UseFormReturn, FieldValues } from 'react-hook-form';
7	import { useDisclosure } from '@chakra-ui/react';
8	import { AuthHelpers, useAuthHelper, useCustomerType } from '@salesforce/commerce-sdk-react';
9	import { useAuthModal, REGISTER_VIEW } from '@salesforce/retail-react-app/app/hooks/use-auth-modal';
10	import { getConfig } from '@salesforce/pwa-kit-runtime/utils/ssr-config';
11	import {
12	  getAuthorizePasswordlessErrorMessage,
13	  getLoginPasswordlessErrorMessage,
14	  getPasswordlessCallbackUrl,
15	} from '@salesforce/retail-react-app/app/utils/auth-utils';
16	import { API_ERROR_MESSAGE } from '@salesforce/retail-react-app/app/constants';
17	import {
18	  setSessionJSONItem,
19	  getSessionJSONItem,
20	  clearSessionJSONItem,
21	  buildRedirectURI,
22	} from '@salesforce/retail-react-app/app/utils/utils';
23	import useMultiSite from '@salesforce/retail-react-app/app/hooks/use-multi-site';
24	import { useCurrentCustomer } from '@salesforce/retail-react-app/app/hooks/use-current-customer';
25	
26	// Matches the ZimmDrawer slide-in animation duration so focus/modal calls land after the
27	// panel is visible and Chakra's FocusLock has initialised.
28	const DRAWER_ANIMATION_DELAY_MS = 150;
29	
30	// Social IDP sign-in triggers a full-page redirect — onAuthSuccess never fires. Persist an
31	// intent before the redirect so the pending wishlist action can be replayed on return.
32	// Keyed by `intentId` (see UseWishlistAuthDrawerParams) rather than a bare flag: the header
33	// and a PDP can both mount their own `useWishlistAuthDrawer` instance on the same returned
34	// page, each with a different `onAuthSuccess` — a bare boolean let whichever instance's
35	// effect ran first steal the intent and fire its own callback instead of the one that
36	// actually initiated the redirect (SFCC-742 review finding).
37	const PENDING_WISHLIST_INTENT_KEY = 'zimmPendingWishlistAction';
38	
39	type PendingWishlistIntent = { intentId: string; timestamp: number };
40	
41	// A cancelled/abandoned IDP round-trip has no reliable "the user said no" signal we can
42	// observe here — the callback route that owns the actual redirect-back is base SFCC code,
43	// not this hook. Bound the blast radius by age instead: long enough for a slow IDP
44	// round-trip, short enough that an abandoned attempt can't misfire a much later, unrelated
45	// registration in the same tab.
46	const PENDING_WISHLIST_INTENT_MAX_AGE_MS = 5 * 60 * 1000; // 5 minutes
47	
48	// Reads the pending intent, transparently discarding (and clearing) one that's aged out.
49	const readPendingWishlistIntent = (): PendingWishlistIntent | undefined => {
50	  const stored = getSessionJSONItem(PENDING_WISHLIST_INTENT_KEY) as PendingWishlistIntent | undefined;
51	  if (!stored) return undefined;
52	  if (Date.now() - stored.timestamp > PENDING_WISHLIST_INTENT_MAX_AGE_MS) {
53	    clearSessionJSONItem(PENDING_WISHLIST_INTENT_KEY);
54	    return undefined;
55	  }
56	  return stored;
57	};
58	
59	const messages = defineMessages({
60	  drawerTitle: {
61	    id: 'wishlist.auth.drawer.title',
62	    defaultMessage: 'Wishlist',
63	  },
64	});
65	
66	const WISHLIST_DESCRIPTION = 'You must log in or create an account to add items to your wishlist.';
67	
68	type UseWishlistAuthDrawerParams = {
69	  onAuthSuccess?: () => void;
70	  /** Identifies which mounted instance initiated a social-IDP redirect, so that after the
71	   *  round-trip only the matching instance's `onAuthSuccess` fires — see
72	   *  `PENDING_WISHLIST_INTENT_KEY`'s comment. Must be stable and distinct per call site
73	   *  (e.g. `'header-wishlist'`, `'pdp-wishlist'`), not per render. */
74	  intentId: string;
75	};
76	
77	export type UseWishlistAuthDrawerReturn = {
78	  isOpen: boolean;
79	  handleDrawerClose: () => void;
80	  handleTriggerClick: (e: SyntheticEvent<HTMLElement>) => void;
81	  /** Ref pointing at the trigger element; passed to ZimmDrawer's finalFocusRef for AC10 focus-return. */
82	  triggerRef: RefObject<HTMLElement>;
83	  drawerTitle: string;
84	  description: string;
85	  emailValue: string;
86	  onEmailChange: (val: string) => void;
87	  onSendCode: () => Promise<{ success: boolean; error?: string } | void>;
88	  onSignInWithApple?: () => void;
89	  onSignInWithGoogle?: () => void;
90	  isSocialEnabled: boolean;
91	  /** Whether the passwordless email login flow is available per site config. */
92	  isPasswordlessEnabled: boolean;
93	  emailInputRef: RefObject<HTMLInputElement>;
94	  /** Error message from a failed social IDP sign-in attempt; absent when no failure has occurred. */
95	  socialError?: string;
96	  onCreateAccount: () => void;
97	  isOtpAuthOpen: boolean;
98	  onOtpAuthClose: () => void;
99	  form: UseFormReturn<FieldValues>;
100	  handlePasswordlessLogin: (email: string) => Promise<{ success: boolean; error?: string }>;
101	  handleOtpVerification: (pwdlessLoginToken: string) => Promise<{ success: boolean; error?: string }>;
102	  registerModal: ReturnType<typeof useAuthModal>;
103	};
104	
105	/**
106	 * Hook — owns all auth-gate state and SFCC SDK integration for the wishlist auth drawer.
107	 * Extracted from `ZimmWishlistAuthDrawer` so that component stays purely presentational.
108	 * Mirrors the same pattern used by SFCC's own `withRegistration` HOC.
109	 *
110	 * @returns All state and event handlers needed to render and drive the auth gate UI.
111	 */
112	export const useWishlistAuthDrawer = ({
113	  onAuthSuccess,
114	  intentId,
115	}: UseWishlistAuthDrawerParams): UseWishlistAuthDrawerReturn => {
116	  const { formatMessage } = useIntl();
117	  const { t } = useUiCopy();
118	  const { data: customer } = useCurrentCustomer();
119	  const { isRegistered } = useCustomerType();
120	  const { isOpen, onOpen, onClose } = useDisclosure();
121	  const [isOtpAuthOpen, setIsOtpAuthOpen] = useState(false);
122	  const [emailValue, setEmailValue] = useState('');
123	  const [socialError, setSocialError] = useState<string | undefined>();
124	  // react-hook-form instance needed by SFCC's OtpAuth component for its internal field registration
125	  const form = useForm();
126	  // Points at the email input so Chakra's Drawer focuses it (not the close button) on open.
127	  const emailInputRef = useRef<HTMLInputElement>(null);
128	
129	  // AC10 focus-return: capture the clicked/focused trigger element at click time.
130	  // React.cloneElement ref forwarding only works if the child uses forwardRef — not
131	  // guaranteed for all consumers. document.activeElement at onClick time is always the
132	  // element that was interacted with, regardless of how the child is implemented.
133	  // Typed as HTMLElement (not HTMLElement | null) to satisfy ZimmDrawer's finalFocusRef prop.
134	  const triggerRef = useRef<HTMLElement>(null as unknown as HTMLElement);
135	
136	  const authorizePasswordlessLogin = useAuthHelper(AuthHelpers.AuthorizePasswordless);
137	  const loginPasswordless = useAuthHelper(AuthHelpers.LoginPasswordlessUser);
138	  const authorizeIDP = useAuthHelper(AuthHelpers.AuthorizeIDP);
139	  // SFCC out-of-the-box registration modal — opened when the user clicks "Create an account"
140	  const registerModal = useAuthModal(REGISTER_VIEW);
141	  const { locale } = useMultiSite();
142	
143	  // eslint-disable-next-line @typescript-eslint/no-explicit-any
144	  const loginConfig = (getConfig().app.login || {}) as any;
145	  const passwordlessConfig = loginConfig.passwordless;
146	  const callbackURL = getPasswordlessCallbackUrl(passwordlessConfig?.callbackURI);
147	  const isSocialEnabled = !!loginConfig.social?.enabled;
148	  const idps: string[] = loginConfig.social?.idps ?? [];
149	  const socialRedirectPath: string = loginConfig.social?.redirectURI ?? '';
150	  const isPasswordlessEnabled = !!passwordlessConfig?.enabled;
151	
152	  // Move focus to the email input once the drawer's enter animation completes.
153	  useEffect(() => {
154	    if (!isOpen) return;
155	    const timer = setTimeout(() => emailInputRef.current?.focus(), DRAWER_ANIMATION_DELAY_MS);
156	    return () => clearTimeout(timer);
157	  }, [isOpen]);
158	
159	  // When the customer transitions to registered while the drawer (or OTP modal) is open,
160	  // close everything and fire the deferred action.
161	  useEffect(() => {
162	    if (isRegistered && (isOpen || isOtpAuthOpen)) {
163	      onClose();
164	      setIsOtpAuthOpen(false);
165	      onAuthSuccess?.();
166	    }
167	  }, [isRegistered]);
168	
169	  // Social IDP sign-in redirects the page — the drawer closes and onAuthSuccess never fires.
170	  // On mount, if the shopper is already registered and a pending intent was stored before the
171	  // redirect, consume it immediately and clear the flag so it does not replay on subsequent
172	  // visits — but only when it's THIS instance's own intent (see PENDING_WISHLIST_INTENT_KEY's
173	  // comment): another `useWishlistAuthDrawer` instance mounted on the same returned page (e.g.
174	  // the header, alongside a PDP) leaves a non-matching intent untouched for its rightful owner.
175	  // Follows the same [isRegistered]-only dep pattern as the effect above: onAuthSuccess and
176	  // intentId are intentionally omitted because the intent fires at most once per redirect
177	  // cycle, and the flag is cleared before any re-render that could change either.
178	  useEffect(() => {
179	    if (!isRegistered) return;
180	    const pending = readPendingWishlistIntent();
181	    if (!pending || pending.intentId !== intentId) return;
182	    clearSessionJSONItem(PENDING_WISHLIST_INTENT_KEY);
183	    onAuthSuccess?.();
184	    // eslint-disable-next-line react-hooks/exhaustive-deps
185	  }, [isRegistered]);
186	
187	  const handleDrawerClose = () => {
188	    onClose();
189	    form.reset();
190	    setEmailValue('');
191	  };
192	
193	  const handleTriggerClick = (e: SyntheticEvent<HTMLElement>) => {
194	    // e.currentTarget is always the element the handler is attached to — reliable across
195	    // mouse and keyboard, unlike document.activeElement which may still be body on click.
196	    triggerRef.current = e.currentTarget;
197	    if (customer?.isRegistered) {
198	      onAuthSuccess?.();
199	    } else {
200	      onOpen();
201	    }
202	  };
203	
204	  const handlePasswordlessLogin = async (email: string) => {
205	    try {
206	      const redirectPath = window.location.pathname + (window.location.search ?? '');
207	      await authorizePasswordlessLogin.mutateAsync({
208	        userid: email,
209	        mode: passwordlessConfig?.mode,
210	        locale: locale.id,
211	        ...(callbackURL && {
212	          callbackURI: (() => {
213	            const url = new URL(callbackURL);
214	            url.searchParams.set('redirectUrl', redirectPath);
215	            return url.toString();
216	          })(),
217	        }),
218	      });
219	      return { success: true };
220	    } catch (error) {
221	      return {
222	        success: false,
223	        error: formatMessage(getAuthorizePasswordlessErrorMessage((error as Error).message)),
224	      };
225	    }
226	  };
227	
228	  const handleOtpVerification = async (pwdlessLoginToken: string) => {
229	    try {
230	      await loginPasswordless.mutateAsync({ pwdlessLoginToken });
231	      return { success: true };
232	    } catch (e) {
233	      const errorData = await (e as { response?: { json: () => Promise<{ message: string }> } }).response?.json();
234	      return { success: false, error: formatMessage(getLoginPasswordlessErrorMessage(errorData?.message)) };
235	    }
236	  };
237	
238	  const onSendCode = async () => {
239	    if (!isPasswordlessEnabled) return;
240	    const result = await handlePasswordlessLogin(emailValue);
241	    if (result.success) {
242	      onClose();
243	      // Brief delay lets the drawer finish its exit transition before OTP modal mounts.
244	      setTimeout(() => setIsOtpAuthOpen(true), DRAWER_ANIMATION_DELAY_MS);
245	    }
246	    return result;
247	  };
248	
249	  const onSignInWithApple =
250	    isSocialEnabled && idps.includes('apple')
251	      ? async () => {
252	          setSocialError(undefined);
253	          try {
254	            setSessionJSONItem('returnToPage', window.location.pathname);
255	            // Persist the wishlist intent before the redirect — the page reloads after social
256	            // auth completes and onAuthSuccess would otherwise never fire.
257	            const intent: PendingWishlistIntent = { intentId, timestamp: Date.now() };
258	            setSessionJSONItem(PENDING_WISHLIST_INTENT_KEY, intent);
259	            await authorizeIDP.mutateAsync({
260	              hint: 'apple',
261	              // Social IDP redirects are browser-only — window.location.origin is always available
262	              // here. useAppOrigin() calls useServerContext() which returns undefined in browser,
263	              // causing a destructuring throw; reading the origin directly avoids the SSR hook.
264	              redirectURI: buildRedirectURI(window.location.origin, socialRedirectPath),
265	            });
266	          } catch {
267	            // mutateAsync rejected before the browser navigated away (e.g. a network/config
268	            // error) — no redirect happened, so the intent just stored is already stale.
269	            // Clear it so it can't misfire a later, unrelated registration in this tab.
270	            clearSessionJSONItem(PENDING_WISHLIST_INTENT_KEY);
271	            setSocialError(formatMessage(API_ERROR_MESSAGE));
272	          }
273	        }
274	      : undefined;
275	
276	  const onSignInWithGoogle =
277	    isSocialEnabled && idps.includes('google')
278	      ? async () => {
279	          setSocialError(undefined);
280	          try {
281	            setSessionJSONItem('returnToPage', window.location.pathname);
282	            // Persist the wishlist intent before the redirect — same reason as Apple above.
283	            const intent: PendingWishlistIntent = { intentId, timestamp: Date.now() };
284	            setSessionJSONItem(PENDING_WISHLIST_INTENT_KEY, intent);
285	            await authorizeIDP.mutateAsync({
286	              hint: 'google',
287	              // Social IDP redirects are browser-only — window.location.origin is always available
288	              // here. useAppOrigin() calls useServerContext() which returns undefined in browser,
289	              // causing a destructuring throw; reading the origin directly avoids the SSR hook.
290	              redirectURI: buildRedirectURI(window.location.origin, socialRedirectPath),
291	            });
292	          } catch {
293	            // Same reasoning as Apple's catch above — no redirect occurred, so clear the
294	            // just-stored intent rather than leaving it to misfire later.
295	            clearSessionJSONItem(PENDING_WISHLIST_INTENT_KEY);
296	            setSocialError(formatMessage(API_ERROR_MESSAGE));
297	          }
298	        }
299	      : undefined;
300	
301	  const onCreateAccount = () => {
302	    handleDrawerClose();
303	    registerModal.onOpen();
304	  };
305	
306	  return {
307	    isOpen,
308	    handleDrawerClose,
309	    handleTriggerClick,
310	    triggerRef,
311	    drawerTitle: formatMessage(messages.drawerTitle),
312	    description: t('login.drawer.wishlist.description', WISHLIST_DESCRIPTION),
313	    emailValue,
314	    onEmailChange: setEmailValue,
315	    onSendCode,
316	    onSignInWithApple,
317	    onSignInWithGoogle,
318	    isSocialEnabled,
319	    isPasswordlessEnabled,
320	    emailInputRef,
321	    socialError,
322	    onCreateAccount,
323	    isOtpAuthOpen,
324	    onOtpAuthClose: () => setIsOtpAuthOpen(false),
325	    form,
326	    handlePasswordlessLogin,
327	    handleOtpVerification,
328	    registerModal,
329	  };
330	};
